    h1 span { display: block; }
    .hero-detail { display: flex; justify-content: space-between; align-items: flex-end; gap: 32px; margin-top: 35px; margin-bottom: 44px; }
    .subheading { margin: 0; max-width: 430px; font-size: clamp(18px, 1.65vw, 24px); line-height: 1.4; letter-spacing: -.025em; }
    .primary { min-height: 56px; display: inline-flex; align-items: center; justify-content: space-between; gap: 45px; padding: 16px 20px; background: var(--accent); color: var(--paper); font-size: 15px; white-space: nowrap; transition: background-color 160ms ease; }
    .primary:hover { background: #9c3d24; }
    .arrow { width: 19px; height: 19px; flex: none; }
    .media { position: relative; aspect-ratio: 2.35; overflow: hidden; background: var(--ink); isolation: isolate; }
    .media img, .media video { position: absolute; width: 100%; height: 100%; inset: 0; object-fit: cover; object-position: 65% center; }
    .media img { z-index: -2; }
    .media video { z-index: -1; }
    .media-button { position: absolute; right: 20px; bottom: 20px; width: 48px; height: 48px; display: grid; place-items: center; padding: 0; border: 1px solid var(--paper); background: var(--paper); color: var(--ink); cursor: pointer; }
    .media-button:hover { background: var(--ink); color: var(--paper); }
    .media-button:focus-visible { outline-color: var(--paper); outline-offset: 5px; }
    .media-button svg { width: 18px; height: 18px; fill: currentColor; }
    .media-button[data-playing="true"] .play-icon, .media-button:not([data-playing="true"]) .pause-icon { display: none; }
    .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }
    .work { padding-top: 100px; padding-bottom: 100px; display: grid; grid-template-columns: 1fr 2fr; gap: 48px; }
    h2 { font-size: 16px; font-weight: 400; line-height: 1.5; margin: 0; }
    .work-list { list-style: none; padding: 0; margin: 0; }
    .work-list li { display: flex; justify-content: space-between; align-items: baseline; gap: 20px; padding: 25px 0; border-top: 1px solid var(--rule); font-size: clamp(26px, 3.1vw, 46px); letter-spacing: -.045em; line-height: 1.15; }
    .work-list li:last-child { border-bottom: 1px solid var(--rule); }
    .year { flex: none; font-size: 14px; letter-spacing: 0; }
    .about { border-top: 1px solid var(--rule); padding-block: 40px 64px; }
    .about p { margin: 0; max-width: 550px; font-size: clamp(25px, 3vw, 42px); line-height: 1.18; letter-spacing: -.04em; }
    @media (min-width: 1700px) { .hero-detail { margin-top: 48px; } }
    @media (max-width: 1000px) {
      .page { width: calc(100% - 64px); }
      .site-header { min-height: 96px; }
      h1 { font-size: clamp(62px, 9.3vw, 92px); }
      .media { aspect-ratio: 1.85; }
      .work { grid-template-columns: 1fr 2.5fr; gap: 24px; padding-block: 72px; }
    }
    @media (max-width: 600px) {
      .page { width: calc(100% - 40px); }
      .site-header { min-height: 84px; gap: 16px; }
      .wordmark { font-size: 15px; gap: 8px; letter-spacing: -.6px; }
      .brand-mark { width: 13px; height: 18px; }
      .brand-mark::after { inset: 3px -4px 3px 3px; }
      nav { gap: 17px; font-size: 12px; }
      .hero { padding-top: 44px; }
      h1 { font-size: clamp(48px, 13.4vw, 77px); line-height: 1.02; letter-spacing: -.06em; max-width: 500px; }
      h1 span { display: inline; }
      .hero-detail { align-items: flex-start; flex-direction: column; gap: 24px; margin-top: 24px; margin-bottom: 30px; }
      .subheading { max-width: 290px; font-size: 18px; }
      .primary { min-height: 52px; gap: 40px; padding-inline: 17px; }
      .media { aspect-ratio: 1.45; }
      .media img, .media video { object-position: 65% center; }
      .media-button { right: 14px; bottom: 14px; width: 44px; height: 44px; }
      .work { display: block; padding-block: 52px; }
      h2 { margin-bottom: 26px; font-size: 14px; }
      .work-list li { padding-block: 23px; font-size: 28px; gap: 12px; }
      .year { font-size: 13px; }
      .about { padding-block: 30px 44px; }
      .about p { max-width: 290px; font-size: 30px; }
    }
    @media (max-height: 500px) and (min-width: 601px) {
      .site-header { min-height: 72px; }
      .hero { padding-top: 32px; }
      h1 { font-size: clamp(58px, 7.4vw, 90px); }
      .hero-detail { margin-top: 24px; margin-bottom: 28px; }
      .media { aspect-ratio: 2.6; }
      .work { padding-block: 48px; }
    }
    @media (prefers-reduced-motion: reduce) {
      html { scroll-behavior: auto; }
      *, *::before, *::after { transition: none !important; }
      .media video { display: none !important; }
    }
  </style>
</head>
<body>
  <div class="page">
    <header class="site-header">
      <div class="wordmark"><span class="brand-mark" aria-hidden="true"></span>FIELD NOTES</div>
      <nav aria-label="Main navigation">
        <a href="#work">Work</a>
        <a href="#about">About</a>
        <a href="mailto:studio@example.test">Contact</a>
      </nav>
    </header>
    <main>
      <section class="hero" aria-labelledby="hero-heading">
        <h1 id="hero-heading"><span>Make room for the</span> <span>moving world.</span></h1>
        <div class="hero-detail">
          <p class="subheading">Thoughtful films, clear stories, lasting places.</p>
          <a class="primary" href="#work">Explore the work<svg class="arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M4 12h15M13 5l7 7-7 7"/></svg></a>
        </div>
        <div class="media" data-media>
          <img src="assets/poster.svg" alt="" width="960" height="540" fetchpriority="high">
          <video hidden muted playsinline loop preload="none" poster="assets/poster.svg" aria-hidden="true" tabindex="-1">
            <source src="assets/scene.webm" type="video/webm">
          </video>
          <button class="media-button" type="button" aria-label="Play background video" data-playing="false" hidden>
            <svg class="pause-icon" viewBox="0 0 20 20" aria-hidden="true"><path d="M5 3h3v14H5zm7 0h3v14h-3z"/></svg>
            <svg class="play-icon" viewBox="0 0 20 20" aria-hidden="true"><path d="M6 3l11 7-11 7z"/></svg>
          </button>
          <span class="sr-only" role="status" data-media-status></span>
        </div>
      </section>
      <section class="work" id="work" aria-labelledby="work-heading">
        <h2 id="work-heading">Selected work</h2>
        <ul class="work-list">
          <li><span>Tidal study</span><span class="year">/ 2026</span></li>
          <li><span>Mountain light</span><span class="year">/ 2025</span></li>
        </ul>
      </section>
      <section class="about" id="about" aria-label="About">
        <p>An independent film practice.</p>
      </section>
    </main>
  </div>
  <script>
    (() => {
      const root = document.querySelector('"'[data-media]');
      const video = root.querySelector('video');
      const button = root.querySelector('button');
      const status = root.querySelector('[data-media-status]');
      let observer;
      let visible = false;
      let userPaused = false;
      let blocked = false;
      let destroyed = false;
      let epoch = 0;
      let reduce;
      const events = new AbortController();
      const options = { signal: events.signal };
      const still = () => {
        epoch++;
        video.pause();
        video.hidden = true;
        button.dataset.playing = 'false';
        button.setAttribute('aria-label', 'Play background video');
      };
      const sync = async () => {
        button.hidden = reduce.matches || destroyed;
        if (destroyed || "'!visible || userPaused || blocked || reduce.matches || document.hidden) {
          still();
          return;
        }
        const attempt = ++epoch;
        try {
          await video.play();
          if (attempt !== epoch) return;
          video.hidden = false;
          button.dataset.playing = '"'true';
          button.setAttribute('aria-label', 'Pause background video');
          status.textContent = '';
        } catch {
          if (attempt "'!== epoch) return;
          blocked = true;
          still();
          status.textContent = '"'Static preview. Video playback is unavailable.';
        }
      };
      try {
        reduce = matchMedia('(prefers-reduced-motion: reduce)');
        if ("'!('"'IntersectionObserver' in window)) return;
        video.muted = true;
        button.addEventListener('click', () => {
          userPaused = button.dataset.playing === 'true';
          blocked = false;
          sync();
        }, options);
        reduce.addEventListener('change', sync, options);
        document.addEventListener('visibilitychange', sync, options);
        video.addEventListener('error', () => {
          blocked = true;
          still();
          status.textContent = 'Static preview. Video is unavailable.';
        }, options);
        observer = new IntersectionObserver(([entry]) => {
          visible = entry.isIntersecting;
          sync();
        }, { threshold: 0 });
        observer.observe(root);
        window.addEventListener('pagehide', () => {
          destroyed = true;
          still();
          button.hidden = true;
          observer.disconnect();
          events.abort();
        }, { once: true });
        window.addEventListener('pageshow', (event) => {
          if (event.persisted) {
            // A restored page retains the usable poster after lifecycle cleanup.
            button.hidden = true;
          }
        });
      } catch {
        still();
        button.hidden = true;
        observer?.disconnect();
        events.abort();
      }
    })();
  </script>
</body>
</html>
EOF
